          const whatDropdown = createEl('div', { style: 'display:none;position:absolute;top:calc(100% + 8px);left:0;width:380px;max-width:calc(100vw - 280px);max-height:80vh;overflow-y:auto;background:rgba(14,18,28,0.97);border:1px solid var(--border-default);border-radius:12px;box-shadow:0 12px 40px rgba(0,0,0,0.55),0 4px 16px rgba(0,0,0,0.35);z-index:100;backdrop-filter:blur(20px);' });
