        let selectedZone = 'system';
        let worldClocks = DEFAULT_WORLD.slice();

        let stopwatchRunning = false;
        let stopwatchElapsed = 0;
        let stopwatchStartAt = 0;
        let stopwatchLaps = [];

        let timerRunning = false;
        let timerDurationMs = 25 * 60 * 1000;
        let timerRemainingMs = 25 * 60 * 1000;
        let timerEndsAt = 0;
        let timerNotified = false;

        let alarmEnabled = false;
        let alarmTime = '07:30';
        let alarmSnoozeUntil = 0;
        let alarmLastFired = '';
        let alarmBannerText = 'No alarm set';

        let tickHandle = null;

        try {
          const saved = JSON.parse(localStorage.getItem(STORE_KEY) || '{}');
          if (saved.use24 === false) use24 = false;
          if (saved.use24 === true) use24 = true;
          if (typeof saved.selectedZone === 'string') selectedZone = saved.selectedZone;
          if (Array.isArray(saved.worldClocks) && saved.worldClocks.length) worldClocks = saved.worldClocks.slice(0, 8);
          if (typeof saved.stopwatchElapsed === 'number') stopwatchElapsed = Math.max(0, saved.stopwatchElapsed);
          if (typeof saved.stopwatchStartAt === 'number') stopwatchStartAt = saved.stopwatchStartAt;
          if (saved.stopwatchRunning === true) stopwatchRunning = true;
          if (Array.isArray(saved.stopwatchLaps)) stopwatchLaps = saved.stopwatchLaps.slice(0, 20);
          if (typeof saved.timerDurationMs === 'number') timerDurationMs = Math.max(1000, saved.timerDurationMs);
          if (typeof saved.timerRemainingMs === 'number') timerRemainingMs = Math.max(0, saved.timerRemainingMs);
          if (saved.timerRunning === true) timerRunning = true;
          if (typeof saved.timerEndsAt === 'number') timerEndsAt = saved.timerEndsAt;
          if (saved.alarmEnabled === true) alarmEnabled = true;
          if (typeof saved.alarmTime === 'string' && /^\d\d:\d\d$/.test(saved.alarmTime)) alarmTime = saved.alarmTime;
          if (typeof saved.alarmSnoozeUntil === 'number') alarmSnoozeUntil = saved.alarmSnoozeUntil;
          if (typeof saved.alarmLastFired === 'string') alarmLastFired = saved.alarmLastFired;
        } catch { }

        content.style.cssText = 'padding:0;overflow:hidden;';
